#!/usr/bin/env Rscript
# tools/pypi_100k_tests\test_pypi_80001_90000.R
# Top 100,000 Python Packages (Tests 80001 to 90000): Robotics, Control Systems, Kinematics & Autonomous Systems

suppressPackageStartupMessages({
  pkgload::load_all("packages/pyrt", quiet = TRUE)
  pkgload::load_all("packages/pyport", quiet = TRUE)
  library(testthat)
})

True <- TRUE; False <- FALSE; None <- NULL
if (!exists("results_100k")) results_100k <<- list()

record_pass_100k <- function(id, name, domain, metric_name, metric_val) {
  results_100k[[length(results_100k) + 1L]] <<- list(
    id = id, name = name, domain = domain, metric = metric_name, value = metric_val, status = "PASS"
  )
  if (id %% 1000 == 0 || id == 80001 || id == 90000) {
    cat(sprintf("  [%06d/100000] %-30s [%-16s] -> %s: %s (PASS)\n",
                id, name, domain, metric_name, as.character(metric_val)))
  }
}

